<?php
require __DIR__.'/config.php';require_owner();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=trim($_POST['name']??'');$username=trim($_POST['username']??'');$password=$_POST['password']??'';$role=$_POST['role']??'cashier';if(!$name||!$username||strlen($password)<8||!in_array($role,['owner','cashier'],true))throw new RuntimeException('Provide a name, username, valid role, and password of at least 8 characters.');$st=$pdo->prepare('INSERT INTO users(name,username,password_hash,role) VALUES(?,?,?,?)');$st->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT),$role]);flash('Account created.');}catch(Throwable $ex){flash($ex->getCode()==='23000'?'That username is already in use.':$ex->getMessage(),'error');}redirect('users.php');}$users=$pdo->query('SELECT id,name,username,role,created_at FROM users ORDER BY id')->fetchAll();$pageTitle='Accounts';require __DIR__.'/partials/header.php';?><div class="page-intro"><div><h1>Accounts & Access</h1><p>Owner can manage accounts. Cashiers can record sales and collect utang payments.</p></div></div><div class="two-col"><section class="panel"><div class="panel-heading"><div><h2>Create account</h2><p>Use a unique username and strong password.</p></div></div><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Display name</label><input name="name" required><label>Username</label><input name="username" required><label>Password (8+ characters)</label><input type="password" name="password" minlength="8" required><label>Role</label><select name="role"><option value="cashier">Cashier</option><option value="owner">Owner</option></select><button class="btn primary">Create account</button></form></section><section class="panel"><div class="panel-heading"><div><h2>Access roles</h2><p>Current permissions</p></div></div><div class="permission-list"><p><b>Owner</b><br><span class="muted">Full dashboard, products, sales, customer balances, expenses, reports, and account management.</span></p><p><b>Cashier</b><br><span class="muted">Dashboard, POS, inventory/product view and edits, customers, utang collections, and reports. Cannot manage accounts or expenses.</span></p></div></section></div><section class="panel section-gap"><div class="panel-heading"><div><h2>Registered accounts</h2><p><?=count($users)?> users</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Created</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?><?=((int)$u['id']===(int)current_user()['id'])?' (you)':''?></td><td><?=e($u['username'])?></td><td><span class="pill <?=e($u['role']==='owner'?'paid':'neutral')?>"><?=e(ucfirst($u['role']))?></span></td><td><?=e($u['created_at'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/partials/footer.php';?>